window.receiveProjectSource({"path": "test/unit/microservices/event_synthesis/services/scoring/test_multi_candidate.py", "lines": ["\"\"\"Multi-candidate orchestrator: tie-break order and conservative LLM partial-outage.", "", "Module-scope env stubs live in the package conftest -- see DAT-6640.", "\"\"\"", "", "import datetime", "from unittest.mock import patch", "from uuid import UUID, uuid4", "", "import pytest", "", "from common.exceptions import AIServiceException", "from common.models.enums import ChatModel", "from microservices.event_synthesis.services.scoring import multi_candidate as mc_module", "from microservices.event_synthesis.services.scoring.composite import score_candidate", "from microservices.event_synthesis.services.scoring.match_config import MatchScoringConfig", "from microservices.event_synthesis.services.scoring.multi_candidate import (", "    MatchOutcome,", "    decide_match,", ")", "from microservices.event_synthesis.services.scoring.types import (", "    DisambiguationOutput,", "    MatchDecision,", "    RawEventForRetrieval,", "    RetrievalChannel,", "    SourceEventCandidate,", ")", "from microservices.event_synthesis.services.tenancy_ownership import TenancyOwnership", "", "pytestmark = pytest.mark.unit", "", "", "class _StubLLMDisambiguator:", "    \"\"\"Test stub for ``LLMDisambiguator``.", "", "    ``responses`` is consumed in order; each entry is either a", "    :class:`DisambiguationOutput` to return, a ``(DisambiguationOutput,", "    ChatModel)`` tuple, or an :class:`Exception` instance to raise.", "    Captures full kwargs per call so context-flow assertions can inspect", "    what the orchestrator passed through.", "    \"\"\"", "", "    def __init__(self, responses: list):", "        self.responses = list(responses)", "        self.calls: list[UUID] = []", "        self.captured_kwargs: list[dict] = []", "        self.chat_model_name = \"gpt-5.4-nano\"", "        # Mirrors the real client: the recheck asks this model, and the", "        # orchestrator also compares against its name to avoid asking twice.", "        self.fallback_chat_model = ChatModel.CLAUDE_HAIKU_4_5", "        self.fallback_chat_model_name = ChatModel.CLAUDE_HAIKU_4_5.value", "", "    async def disambiguate(self, **kwargs):  # type: ignore[no-untyped-def]", "        candidate = kwargs[\"candidate\"]", "        self.calls.append(candidate.source_event_id)", "        self.captured_kwargs.append(kwargs)", "        if not self.responses:", "            raise AssertionError(\"Stub LLM exhausted\")", "        nxt = self.responses.pop(0)", "        if isinstance(nxt, Exception):", "            raise nxt", "        # A bare output reports whichever model was actually asked, so a recheck", "        # that stopped forwarding its override fails here instead of passing.", "        if isinstance(nxt, tuple):", "            return nxt", "        return nxt, kwargs.get(\"chat_model_override\") or ChatModel.GPT_5_4_NANO", "", "", "def _config() -> MatchScoringConfig:", "    return MatchScoringConfig(high_threshold=0.82, low_threshold=0.55)", "", "", "def _make_incoming(", "    *,", "    cat_id: UUID,", "    type_id: UUID,", "    entity_ids: tuple[UUID, ...],", "    event_date: datetime.date | None = None,", "    event_date_precision: str = \"exact_date\",", ") -> RawEventForRetrieval:", "    return RawEventForRetrieval(", "        raw_event_id=uuid4(),", "        event_category_id=cat_id,", "        event_type_id=type_id,", "        event_date=event_date or datetime.date(2026, 5, 1),", "        event_date_precision=event_date_precision,", "        summary=\"incoming\",", "        entity_ids=entity_ids,", "        tenancy_ownership=TenancyOwnership.platform(),", "    )", "", "", "def _make_candidate(", "    *,", "    cat_id: UUID,", "    type_id: UUID,", "    candidate_entity_ids: set[UUID],", "    event_date: datetime.date | None = None,", "    summary_similarity: float | None = None,", "    source_event_id: UUID | None = None,", "    event_date_precision: str = \"exact_date\",", ") -> SourceEventCandidate:", "    return SourceEventCandidate(", "        source_event_id=source_event_id or uuid4(),", "        candidate_entity_ids=candidate_entity_ids,", "        event_category_id=cat_id,", "        event_type_id=type_id,", "        event_date=event_date or datetime.date(2026, 5, 1),", "        event_date_precision=event_date_precision,", "        summary_similarity=summary_similarity,", "    )", "", "", "async def test_merge_confirmed_short_circuits_llm():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    e1, e2 = uuid4(), uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1, e2))", "    confirmed = _make_candidate(", "        cat_id=cat, type_id=type_id, candidate_entity_ids={e1, e2}, summary_similarity=0.95", "    )", "    ambiguous_1 = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids={e1},", "        summary_similarity=0.6,", "    )", "    ambiguous_2 = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids={e2},", "        summary_similarity=0.5,", "    )", "    llm = _StubLLMDisambiguator([])", "", "    outcome = await decide_match(incoming, [ambiguous_1, confirmed, ambiguous_2], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == confirmed.source_event_id", "    assert llm.calls == []", "    assert outcome.llm_attempts == ()", "", "", "async def test_two_ambiguous_llm_returns_false_routes_create_new():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = (", "        uuid4()", "    )  # different type \u2192 type_score=0.35 (same cat) \u2192 composite in NEEDS_LLM band", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    amb1 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.6", "    )", "    amb2 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"diff\"),", "            DisambiguationOutput(same_event=False, confidence=0.85, rationale=\"diff\"),", "        ]", "    )", "", "    outcome = await decide_match(incoming, [amb1, amb2], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert outcome.chosen_source_event_id is None", "    assert len(outcome.llm_attempts) == 2", "    assert all(a.error is None for a in outcome.llm_attempts)", "", "", "async def test_first_llm_true_short_circuits_remaining_calls():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()  # different type \u2192 composite in NEEDS_LLM band", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    amb1 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "    amb2 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.6", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=True, confidence=0.95, rationale=\"match\"),", "            DisambiguationOutput(same_event=False, confidence=0.85, rationale=\"never called\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [amb1, amb2], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.MERGE_CONFIRMED", "    assert len(llm.calls) == 1", "    assert len(outcome.llm_attempts) == 1", "", "", "async def test_all_llm_errors_route_retry_or_dlq():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()  # different type \u2192 composite in NEEDS_LLM band", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    amb1 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "", "    llm = _StubLLMDisambiguator([AIServiceException(\"upstream 503\")])", "    outcome = await decide_match(incoming, [amb1], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.RETRY_OR_DLQ", "    assert outcome.chosen_source_event_id is None", "    assert len(outcome.llm_attempts) == 1", "    assert outcome.llm_attempts[0].error is not None", "", "", "async def test_first_error_stops_iteration_immediately():", "    \"\"\"Conservative partial-outage: first LLM error short-circuits iteration.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()  # different type \u2192 composite in NEEDS_LLM band", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    amb1 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "    amb2 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.6", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            AIServiceException(\"upstream 503\"),", "            DisambiguationOutput(same_event=False, confidence=0.99, rationale=\"never called\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [amb1, amb2], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.RETRY_OR_DLQ", "    assert len(llm.calls) == 1  # only the first ambiguous candidate dispatched", "", "", "async def test_error_after_prior_false_still_routes_retry_or_dlq():", "    \"\"\"Conservative partial-outage: an error after prior False overrides CREATE_NEW.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()  # different type \u2192 composite in NEEDS_LLM band", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    amb1 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "    amb2 = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.6", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.85, rationale=\"diff\"),", "            AIServiceException(\"upstream 503\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [amb1, amb2], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.RETRY_OR_DLQ", "    assert len(outcome.llm_attempts) == 2", "    assert outcome.llm_attempts[0].error is None", "    assert outcome.llm_attempts[1].error is not None", "", "", "async def test_tie_break_uses_ascending_uuid_terminator():", "    \"\"\"Two candidates identical on every score factor should sort by UUID ascending.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    # Two MERGE_CONFIRMED candidates with identical signals.", "    uuid_high = UUID(\"ffffffff-ffff-4fff-bfff-ffffffffffff\")", "    uuid_low = UUID(\"00000000-0000-4000-b000-000000000000\")", "    cand_high = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids={e1},", "        summary_similarity=0.95,", "        source_event_id=uuid_high,", "    )", "    cand_low = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids={e1},", "        summary_similarity=0.95,", "        source_event_id=uuid_low,", "    )", "    llm = _StubLLMDisambiguator([])", "", "    # Run twice with shuffled input \u2014 outcome must be stable.", "    out1 = await decide_match(incoming, [cand_high, cand_low], cfg, llm)  # type: ignore[arg-type]", "    out2 = await decide_match(incoming, [cand_low, cand_high], cfg, llm)  # type: ignore[arg-type]", "    assert out1.chosen_source_event_id == uuid_low", "    assert out2.chosen_source_event_id == uuid_low", "    assert out1.candidate_scores[0].source_event_id == uuid_low", "", "", "async def test_empty_candidates_routes_create_new():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    llm = _StubLLMDisambiguator([])", "    outcome = await decide_match(incoming, [], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert outcome.candidate_scores == ()", "    assert outcome.llm_attempts == ()", "", "", "async def test_all_below_low_threshold_routes_create_new_no_llm():", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    # All factors disagree to push composite below 0.55.", "    cand = SourceEventCandidate(", "        source_event_id=uuid4(),", "        candidate_entity_ids={uuid4()},  # different entity", "        event_category_id=uuid4(),  # different category", "        event_type_id=uuid4(),  # different type", "        event_date=datetime.date(2099, 1, 1),  # very far away", "        event_date_precision=\"exact_date\",", "        summary_similarity=0.1,", "    )", "    llm = _StubLLMDisambiguator([])", "    outcome = await decide_match(incoming, [cand], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert llm.calls == []", "", "", "async def test_orchestrator_threads_context_fields_to_disambiguator():", "    \"\"\"Orchestrator threads key_details, entities_involved, and candidate summary through.", "", "    When ``RawEventForRetrieval`` and ``SourceEventCandidate`` carry these", "    context fields, ``_attempt_llm`` must thread them into", "    ``LLMDisambiguator.disambiguate(...)`` so the LLM gets full context.", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = RawEventForRetrieval(", "        raw_event_id=uuid4(),", "        event_category_id=cat,", "        event_type_id=type_id,", "        event_date=datetime.date(2026, 5, 1),", "        event_date_precision=\"exact_date\",", "        summary=\"incoming summary\",", "        entity_ids=(e1,),", "        key_details={\"acquirer\": \"Acme\", \"deal_value_usd\": 100_000_000},", "        entities_involved=[{\"name\": \"Acme\", \"role\": \"subject\"}],", "        tenancy_ownership=TenancyOwnership.platform(),", "    )", "    candidate = SourceEventCandidate(", "        source_event_id=uuid4(),", "        candidate_entity_ids={e1},", "        event_category_id=cat,", "        event_type_id=amb_type_id,  # different type \u2192 ambiguous band", "        event_date=datetime.date(2026, 5, 1),", "        event_date_precision=\"exact_date\",", "        summary_similarity=0.7,", "        summary=\"candidate summary\",", "        key_details={\"target\": \"Beta\"},", "        entities_involved=[{\"name\": \"Beta\", \"role\": \"object\"}],", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=True, confidence=0.9, rationale=\"x\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.MERGE_CONFIRMED", "    assert len(llm.captured_kwargs) == 1", "    kw = llm.captured_kwargs[0]", "    assert kw[\"incoming_key_details\"] == {\"acquirer\": \"Acme\", \"deal_value_usd\": 100_000_000}", "    assert kw[\"incoming_entities\"] == [{\"name\": \"Acme\", \"role\": \"subject\"}]", "    assert kw[\"candidate_summary\"] == \"candidate summary\"", "    assert kw[\"candidate_key_details\"] == {\"target\": \"Beta\"}", "    assert kw[\"candidate_entities\"] == [{\"name\": \"Beta\", \"role\": \"object\"}]", "", "", "# ---------- no auto-merge without entity overlap ----------", "", "", "async def test_both_empty_same_type_consults_llm_instead_of_auto_merging():", "    \"\"\"No shared entities but matching type/category/date renormalizes to composite ~1.0.", "", "    Without an entity anchor the scorer must not auto-merge: it routes to the LLM, and a", "    \"different event\" verdict creates a new source_event.", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=())", "    candidate = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids=set(),", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"unrelated\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert len(llm.calls) == 1  # the LLM was consulted -> no silent auto-merge", "    assert len(outcome.llm_attempts) == 1", "    assert outcome.candidate_scores[0].entity_overlap_score is None", "", "", "async def test_both_empty_same_type_llm_true_still_merges():", "    \"\"\"The guard caps auto-merge but a genuine match is still reachable via the LLM.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=())", "    candidate = _make_candidate(", "        cat_id=cat,", "        type_id=type_id,", "        candidate_entity_ids=set(),", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=True, confidence=0.95, rationale=\"same event\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == candidate.source_event_id", "    assert len(llm.calls) == 1", "", "", "async def test_coarse_signals_only_create_new_without_llm():", "    \"\"\"No entities and no event_type on either side: category + temporal renormalize to a", "    high composite, but coarse signals alone must never merge or reach the LLM -> CREATE_NEW.", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    d = datetime.date(2026, 5, 1)", "", "    incoming = RawEventForRetrieval(", "        raw_event_id=uuid4(),", "        event_category_id=cat,", "        event_type_id=None,", "        event_date=d,", "        event_date_precision=\"exact_date\",", "        summary=\"incoming\",", "        entity_ids=(),", "        tenancy_ownership=TenancyOwnership.platform(),", "    )", "    candidate = SourceEventCandidate(", "        source_event_id=uuid4(),", "        candidate_entity_ids=set(),", "        event_category_id=cat,", "        event_type_id=None,", "        event_date=d,", "        event_date_precision=\"exact_date\",", "        summary_similarity=None,", "    )", "", "    llm = _StubLLMDisambiguator([])", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert llm.calls == []", "    assert outcome.llm_attempts == ()", "", "", "async def test_asymmetric_entity_absence_creates_new_without_llm():", "    \"\"\"The confirmed regression: incoming resolved zero entities, candidate has one,", "    neither has an event_type. The entity factor scores 0.0, so the composite", "    lands at 0.50 -> CREATE_NEW deterministically. The stub is primed to say", "    ``same_event=True`` yet must never be called -- proving the scorer never even reaches", "    the LLM for this profile (matching the production ``llm_attempts: []`` shape).", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    d = datetime.date(2026, 5, 1)", "    e1 = uuid4()", "", "    incoming = RawEventForRetrieval(", "        raw_event_id=uuid4(),", "        event_category_id=cat,", "        event_type_id=None,", "        event_date=d,", "        event_date_precision=\"exact_date\",", "        summary=\"incoming\",", "        entity_ids=(),", "        tenancy_ownership=TenancyOwnership.platform(),", "    )", "    candidate = SourceEventCandidate(", "        source_event_id=uuid4(),", "        candidate_entity_ids={e1},", "        event_category_id=cat,", "        event_type_id=None,", "        event_date=d,", "        event_date_precision=\"exact_date\",", "        summary_similarity=None,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=True, confidence=0.95, rationale=\"never called\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert llm.calls == []  # deterministic CREATE_NEW -> LLM never consulted", "    assert outcome.llm_attempts == ()", "    assert outcome.candidate_scores[0].entity_overlap_score == 0.0", "", "", "async def test_orchestrator_handles_missing_context_with_safe_defaults():", "    \"\"\"Backward-compat: when context fields are None, the orchestrator passes safe defaults.", "", "    DAT-6131/DAT-6134 may roll out the new fields gradually. Until they", "    populate them, ``_attempt_llm`` must not crash on ``None`` and the", "    disambiguator's empty-default handling kicks in.", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    # candidate has no summary / key_details / entities_involved (defaults None)", "    candidate = _make_candidate(", "        cat_id=cat,", "        type_id=amb_type_id,", "        candidate_entity_ids={e1},", "        summary_similarity=0.7,", "    )", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.6, rationale=\"differ\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    kw = llm.captured_kwargs[0]", "    # Defaults for missing context: candidate_summary=\"\" (from \"or \"\" fallback),", "    # the rest are passed as None and the disambiguator handles them.", "    assert kw[\"candidate_summary\"] == \"\"", "    assert kw[\"incoming_key_details\"] is None", "    assert kw[\"candidate_key_details\"] is None", "", "", "async def test_llm_attempt_records_actual_chat_model_used():", "    \"\"\"LLMAttempt.chat_model reflects the provider that produced the response.", "", "    When the disambiguator falls back to Claude, the recorded attempt must", "    show the fallback model \u2014 not the primary \u2014 so audit logs accurately", "    attribute the call.", "    \"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    candidate = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "    # Stub returns (output, ChatModel.CLAUDE_HAIKU_4_5) \u2014 simulates fallback success.", "    fallback_response = (", "        DisambiguationOutput(same_event=False, confidence=0.6, rationale=\"differ\"),", "        ChatModel.CLAUDE_HAIKU_4_5,", "    )", "    llm = _StubLLMDisambiguator([fallback_response])", "    outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    assert len(outcome.llm_attempts) == 1", "    assert outcome.llm_attempts[0].chat_model == ChatModel.CLAUDE_HAIKU_4_5.value", "", "", "# ---------------------------------------------------------------------------", "# Structured match-decision logging", "# ---------------------------------------------------------------------------", "", "_LOG_SENTINEL = \"SENTINEL_LEAK_TOKEN_DO_NOT_LOG\"", "_LOGGER_TARGET = \"microservices.event_synthesis.services.scoring.multi_candidate.logger\"", "", "", "async def test_decide_match_emits_structured_log_on_merge_confirmed():", "    \"\"\"Deterministic merge path emits one structured log with raw_event_id, decision, top blob.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    candidate = _make_candidate(", "        cat_id=cat, type_id=type_id, candidate_entity_ids={e1}, summary_similarity=0.95", "    )", "    llm = _StubLLMDisambiguator([])", "", "    with patch(_LOGGER_TARGET) as mock_logger:", "        outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "", "    assert outcome.decision == MatchDecision.MERGE_CONFIRMED", "    mock_logger.info.assert_called_once()", "    args, kwargs = mock_logger.info.call_args", "    assert args == (\"match_decision_complete\",)", "    assert kwargs[\"component\"] == \"ess_scoring\"", "    assert kwargs[\"raw_event_id\"] == str(incoming.raw_event_id)", "    assert kwargs[\"decision\"] == MatchDecision.MERGE_CONFIRMED.value", "    assert kwargs[\"chosen_source_event_id\"] == str(candidate.source_event_id)", "    assert kwargs[\"candidate_count\"] == 1", "    assert kwargs[\"top_score_blob\"][\"decision\"] == MatchDecision.MERGE_CONFIRMED.value", "    assert kwargs[\"llm_attempts\"] == []", "", "", "async def test_decide_match_logs_empty_top_blob_when_no_candidates():", "    \"\"\"Empty-candidate path still logs the decision; top_score_blob is None, candidate_count 0.\"\"\"", "    cfg = _config()", "    incoming = _make_incoming(cat_id=uuid4(), type_id=uuid4(), entity_ids=(uuid4(),))", "    llm = _StubLLMDisambiguator([])", "", "    with patch(_LOGGER_TARGET) as mock_logger:", "        outcome = await decide_match(incoming, [], cfg, llm)  # type: ignore[arg-type]", "", "    assert outcome.decision == MatchDecision.CREATE_NEW", "    kwargs = mock_logger.info.call_args.kwargs", "    assert kwargs[\"candidate_count\"] == 0", "    assert kwargs[\"top_score_blob\"] is None", "    assert kwargs[\"chosen_source_event_id\"] is None", "", "", "async def test_decide_match_log_excludes_summaries_key_details_entities_and_rationale():", "    \"\"\"Sentinel guard: source text and rationale must never appear in the structured log.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = RawEventForRetrieval(", "        raw_event_id=uuid4(),", "        event_category_id=cat,", "        event_type_id=type_id,", "        event_date=datetime.date(2026, 5, 1),", "        event_date_precision=\"exact_date\",", "        summary=f\"raw {_LOG_SENTINEL} summary\",", "        entity_ids=(e1,),", "        key_details={\"leaky_kd\": _LOG_SENTINEL},", "        entities_involved=[{\"name\": _LOG_SENTINEL, \"role\": \"subject\"}],", "        tenancy_ownership=TenancyOwnership.platform(),", "    )", "    candidate = SourceEventCandidate(", "        source_event_id=uuid4(),", "        candidate_entity_ids={e1},", "        event_category_id=cat,", "        event_type_id=amb_type_id,", "        event_date=datetime.date(2026, 5, 1),", "        event_date_precision=\"exact_date\",", "        summary_similarity=0.7,", "        summary=f\"cand {_LOG_SENTINEL} summary\",", "        key_details={\"leaky_kd_cand\": _LOG_SENTINEL},", "        entities_involved=[{\"name\": _LOG_SENTINEL, \"role\": \"object\"}],", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(", "                same_event=True,", "                confidence=0.9,", "                rationale=f\"rationale leaks {_LOG_SENTINEL} verbatim\",", "            )", "        ]", "    )", "", "    with patch(_LOGGER_TARGET) as mock_logger:", "        await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "", "    # Reconstruct everything that would have been emitted.", "    haystack_parts: list[str] = []", "    for call in mock_logger.info.call_args_list:", "        haystack_parts.append(str(call.args))", "        haystack_parts.append(str(call.kwargs))", "    haystack = \"\\n\".join(haystack_parts)", "    assert mock_logger.info.called, \"expected at least one match_decision_complete log call\"", "    assert _LOG_SENTINEL not in haystack, (", "        \"decide_match leaked sensitive content into structured log. \"", "        \"Inspect _record_match_decision() - only safe metadata is allowed.\"", "    )", "", "", "async def test_decide_match_log_excludes_exception_message_on_llm_error():", "    \"\"\"Sentinel guard on the error path: exception messages must never leak via llm_attempts[].error.\"\"\"", "    cfg = _config()", "    cat = uuid4()", "    type_id = uuid4()", "    amb_type_id = uuid4()", "    e1 = uuid4()", "", "    incoming = _make_incoming(cat_id=cat, type_id=type_id, entity_ids=(e1,))", "    candidate = _make_candidate(", "        cat_id=cat, type_id=amb_type_id, candidate_entity_ids={e1}, summary_similarity=0.7", "    )", "", "    # Exception whose repr() embeds the sentinel \u2014 simulates a chained", "    # ValidationError / ParseError that quotes LLM output or input fragments.", "    leaky_exc = AIServiceException(f\"upstream parse error containing {_LOG_SENTINEL} verbatim\")", "    llm = _StubLLMDisambiguator([leaky_exc])", "", "    with patch(_LOGGER_TARGET) as mock_logger:", "        outcome = await decide_match(incoming, [candidate], cfg, llm)  # type: ignore[arg-type]", "", "    assert outcome.decision == MatchDecision.RETRY_OR_DLQ", "    assert mock_logger.info.called", "    haystack_parts: list[str] = []", "    for call in mock_logger.info.call_args_list:", "        haystack_parts.append(str(call.args))", "        haystack_parts.append(str(call.kwargs))", "    haystack = \"\\n\".join(haystack_parts)", "    assert _LOG_SENTINEL not in haystack, (", "        \"decide_match leaked exception message into structured log. \"", "        \"_attempt_llm should record only the exception class name, not repr(e).\"", "    )", "    # Sanity-check that we DID record an error (just sanitized).", "    logged_attempts = mock_logger.info.call_args.kwargs[\"llm_attempts\"]", "    assert len(logged_attempts) == 1", "    assert logged_attempts[0][\"error\"] == \"AIServiceException\"", "", "", "def test_decision_log_pairs_each_blob_with_its_candidate(monkeypatch):", "    \"\"\"Each logged blob must carry the candidate it belongs to.", "", "    An anonymous blob cannot distinguish \"the prior event was scored and", "    rejected\" from \"a different event was retrieved instead\" -- which is the only", "    question the decision log exists to answer. Pairing is the feature, so it is", "    asserted rather than assumed.", "    \"\"\"", "    from microservices.event_synthesis.services.scoring import multi_candidate as mc", "", "    captured: dict = {}", "", "    def _capture(event: str, **kwargs):", "        if event == \"match_decision_complete\":", "            captured.update(kwargs)", "", "    monkeypatch.setattr(mc.logger, \"info\", _capture)", "", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    entity = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(entity,))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={entity},", "        summary_similarity=0.9,", "    )", "    candidate.retrieval_channels = {RetrievalChannel.ENTITY_OVERLAP}", "    candidate.retrieval_reasons = [\"shared entity\"]", "", "    scored = score_candidate(incoming, candidate, cfg)", "    outcome = MatchOutcome(", "        decision=scored.decision,", "        chosen_source_event_id=None,", "        candidate_scores=(scored,),", "        llm_attempts=(),", "    )", "", "    mc._record_match_decision(incoming, outcome, cfg, [candidate])", "", "    blobs = captured[\"candidate_score_blobs\"]", "    assert len(blobs) == 1", "    entry = blobs[0]", "    assert entry[\"source_event_id\"] == str(candidate.source_event_id)", "    assert entry[\"retrieval_channels\"] == [str(RetrievalChannel.ENTITY_OVERLAP)]", "    assert entry[\"retrieval_reasons\"] == [\"shared entity\"]", "    # Thresholds already travel inside the blob; they are not re-added alongside it.", "    assert entry[\"score_blob\"][\"thresholds\"] == {", "        \"high\": cfg.high_threshold,", "        \"low\": cfg.low_threshold,", "        \"min_summary_for_auto_merge\": 0.75,", "    }", "", "", "def test_decision_log_names_every_scored_candidate_beyond_the_blob_cap(monkeypatch):", "    \"\"\"The roster covers all scored candidates; only the top few carry score blobs.", "", "    Score blobs are capped for size, which leaves \"absent from the blobs\" ambiguous", "    between scored-and-rejected and never-scored. The roster removes that ambiguity", "    at the cost of one string per candidate.", "    \"\"\"", "    from microservices.event_synthesis.services.scoring import multi_candidate as mc", "", "    captured: dict = {}", "", "    def _capture(event: str, **kwargs):", "        if event == \"match_decision_complete\":", "            captured.update(kwargs)", "", "    monkeypatch.setattr(mc.logger, \"info\", _capture)", "", "    cfg = _config()", "    cat_id, type_id, entity = uuid4(), uuid4(), uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(entity,))", "    candidate_total = mc._LOGGED_CANDIDATE_BLOBS + 2", "    candidates = [", "        _make_candidate(", "            cat_id=cat_id,", "            type_id=type_id,", "            candidate_entity_ids={entity},", "            summary_similarity=0.9,", "        )", "        for _ in range(candidate_total)", "    ]", "    scores = tuple(score_candidate(incoming, c, cfg) for c in candidates)", "    outcome = MatchOutcome(", "        decision=scores[0].decision,", "        chosen_source_event_id=None,", "        candidate_scores=scores,", "        llm_attempts=(),", "    )", "", "    mc._record_match_decision(incoming, outcome, cfg, candidates)", "", "    roster = captured[\"scored_candidate_ids\"]", "    blob_ids = [entry[\"source_event_id\"] for entry in captured[\"candidate_score_blobs\"]]", "", "    assert len(blob_ids) == mc._LOGGED_CANDIDATE_BLOBS", "    assert roster == [str(s.source_event_id) for s in scores]", "    assert len(roster) == candidate_total", "    # The candidates past the blob cap are still identifiable as scored.", "    assert set(blob_ids) < set(roster)", "    for scored in scores[mc._LOGGED_CANDIDATE_BLOBS :]:", "        assert str(scored.source_event_id) in roster", "        assert str(scored.source_event_id) not in blob_ids", "", "", "async def test_a_barely_confident_rejection_is_as_decisive_as_a_certain_one():", "    \"\"\"Confidence travels in the attempt metadata and changes no decision.", "", "    ``decide_match`` reads only ``same_event`` on the rejection path, so a verdict", "    the model is barely sure of discards a candidate as firmly as a certain one.", "    Pinned, not fixed: measured rejections come back at 0.99, so there is no", "    low-confidence population to act on. Says nothing about the confirmation path.", "    \"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        # The text says one story, but stays under the recheck floor: this test is", "        # about the first-pass answer, not the second opinion.", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.05, rationale=\"barely sure\")]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    # The near-coin-flip rejection is honoured in full.", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert outcome.chosen_source_event_id is None", "    # The value is carried for observability, so a future change has it to read.", "    assert [(a.same_event, a.confidence) for a in outcome.llm_attempts] == [(False, 0.05)]", "", "", "async def test_a_confident_rejection_of_unrelated_text_is_the_same_path():", "    \"\"\"The paired case: when the text disagrees too, the same create is correct.", "", "    Identical decision, opposite quality of evidence -- the contrast the test", "    above rests on.", "    \"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=0.20,  # the text says different stories", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.99, rationale=\"clearly different\")]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert [(a.same_event, a.confidence) for a in outcome.llm_attempts] == [(False, 0.99)]", "", "", "async def test_the_disambiguation_queue_is_capped_at_max_llm_calls():", "    \"\"\"More ambiguous candidates than slots means the tail is never adjudicated.", "", "    ``ambiguous[:cap]`` had no behavioural coverage, so a change to the cap or the", "    slicing could land without a test moving. Asserts how many candidates are", "    adjudicated, never which, so ordering stays a separate concern.", "    \"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "", "    config = _config()", "    candidates = [", "        _make_candidate(", "            cat_id=cat_id,", "            type_id=type_id,", "            candidate_entity_ids={shared, uuid4(), uuid4()},", "            summary_similarity=sim,", "        )", "        for sim in (0.60, 0.58, 0.56, 0.54, 0.52)", "    ]", "    assert len(candidates) > config.max_llm_calls, \"fixture must exceed the cap\"", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"different\")]", "        * len(candidates)", "    )", "    outcome = await decide_match(incoming, candidates, config, llm)", "", "    # Every candidate was ambiguous, so the cap is the only thing limiting dispatch.", "    assert all(s.decision is MatchDecision.NEEDS_LLM for s in outcome.candidate_scores)", "    # Distinct, not merely three calls: a slicing or dedup bug that dispatched one", "    # candidate twice would adjudicate fewer events than the cap implies.", "    assert len(llm.calls) == config.max_llm_calls", "    assert len(set(llm.calls)) == config.max_llm_calls", "    assert set(llm.calls) <= {c.source_event_id for c in candidates}", "    assert outcome.decision is MatchDecision.CREATE_NEW", "", "", "async def test_the_true_sibling_is_asked_before_stronger_scoring_distractors():", "    \"\"\"The scarce LLM slots go to the strongest text evidence, not the top composite.", "", "    Unrelated same-day events share short entity lists and often match on type", "    exactly, which outscores a genuine sibling the extractor filed under a different", "    type. Ordering by composite would spend every slot on them.", "    \"\"\"", "    cat_id, type_id, other_type_id = uuid4(), uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "", "    distractors = [", "        _make_candidate(", "            cat_id=cat_id,", "            type_id=type_id,  # exact type match flatters the composite", "            candidate_entity_ids={shared, uuid4(), uuid4()},", "            summary_similarity=0.35,  # but the text is unrelated", "        )", "        for _ in range(3)", "    ]", "    sibling = _make_candidate(", "        cat_id=cat_id,", "        type_id=other_type_id,  # one story the extractor could not file consistently", "        candidate_entity_ids={shared, uuid4(), uuid4(), uuid4(), uuid4()},", "        summary_similarity=0.90,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=True, confidence=0.95, rationale=\"same story\")]", "    )", "    outcome = await decide_match(incoming, [*distractors, sibling], _config(), llm)", "", "    # Pin the trap this guards: the distractors really do outrank on composite.", "    by_id = {s.source_event_id: s for s in outcome.candidate_scores}", "    assert by_id[sibling.source_event_id].composite_score < min(", "        by_id[d.source_event_id].composite_score for d in distractors", "    )", "", "    assert llm.calls == [sibling.source_event_id], (", "        \"The queue spent its slots on higher-scoring candidates with unrelated text.\"", "    )", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == sibling.source_event_id", "", "", "async def test_a_candidate_with_no_measured_similarity_is_asked_last():", "    \"\"\"An unmeasured summary is not evidence, so it does not win a slot.", "", "    An absent factor renormalises the rest upward, so ordering by composite treats", "    it as a strong signal and lets it crowd out a measured one.", "    \"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "", "    unmeasured = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=None,", "    )", "    measured = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=0.60,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"different\")] * 2", "    )", "    await decide_match(incoming, [unmeasured, measured], _config(), llm)", "", "    assert llm.calls[0] == measured.source_event_id", "", "", "async def test_each_decision_counts_its_outcome_and_every_llm_call(monkeypatch):", "    \"\"\"Outcome distribution and dispatch volume both get a counter.", "", "    Deliberately not ``ess.dedupe.decision``: that name is documented for the", "    synthesis vocabulary (create / merge / link / duplicate_document / ambiguous),", "    which this layer never produces, so emitting scorer bands under it would leave", "    the documented alerts matching nothing.", "    \"\"\"", "    cfg = _config()", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics, \"incr\", lambda name, tags=None: emitted.append((name, tags or []))", "    )", "", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.99, rationale=\"different\")]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    # Exactly once: the alerts read shares, so a double emission skews denominators.", "    decisions = [t for n, t in emitted if n == \"ess.scoring.decision\"]", "    assert decisions == [[f\"decision:{outcome.decision.value}\"]]", "    # One dispatch counter per call, matching the attempts actually made.", "    dispatches = [n for n, _ in emitted if n == \"ess.scoring.llm_dispatch\"]", "    assert len(dispatches) == len(outcome.llm_attempts) == 1", "    # needs_llm is never a final decision, so the band tag cannot report dispatch.", "    assert outcome.decision is not MatchDecision.NEEDS_LLM", "", "", "async def test_every_llm_answer_counts_its_classification(monkeypatch):", "    \"\"\"Rejections and confirmations are counted separately, per answer.", "", "    ``ess.scoring.llm_dispatch`` gives total adjudication volume only. Without a", "    result counter, \"how often does the model say different event\" is answerable", "    only by reading individual decision records.", "    \"\"\"", "    cfg = _config()", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics, \"incr\", lambda name, tags=None: emitted.append((name, tags or []))", "    )", "", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    # Both below llm_recheck_min_summary: this test counts first-pass answers, and", "    # a recheck would consume the second response and merge the wrong candidate.", "    first = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "    second = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=cfg.llm_recheck_min_summary - 0.03,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.99, rationale=\"different\"),", "            DisambiguationOutput(same_event=True, confidence=0.95, rationale=\"same\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [first, second], _config(), llm)", "", "    results = [t for n, t in emitted if n == \"ess.scoring.llm_result\"]", "    # One result per answer, in the order the answers came back.", "    assert results == [[\"same_event:false\"], [\"same_event:true\"]]", "    assert len(outcome.llm_attempts) == 2", "    # Both from first-pass dispatch: the same counts would hold if a recheck had", "    # consumed the second response, making this pass while measuring something else.", "    assert [a.recheck for a in outcome.llm_attempts] == [False, False]", "    assert outcome.chosen_source_event_id == second.source_event_id", "", "", "async def test_a_failed_call_counts_as_an_error_result_not_a_rejection(monkeypatch):", "    \"\"\"An outage is not a \"different event\" answer and must not be counted as one.", "", "    The error tag is what carries the failure rate: a result is emitted on every", "    path, so the counter total matches dispatch and only the tag split is a signal.", "    \"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics, \"incr\", lambda name, tags=None: emitted.append((name, tags or []))", "    )", "", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4()},", "        summary_similarity=0.90,", "    )", "", "    llm = _StubLLMDisambiguator([RuntimeError(\"provider down\")])", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.RETRY_OR_DLQ", "    results = [t for n, t in emitted if n == \"ess.scoring.llm_result\"]", "    assert results == [[\"same_event:error\"]]", "    # The pair that makes the failure rate readable: one dispatch, one error result.", "    dispatches = [n for n, _ in emitted if n == \"ess.scoring.llm_dispatch\"]", "    assert len(dispatches) == 1", "", "", "def _reported_shape(*, cat_id, type_id, shared, other):", "    \"\"\"The shape named in the defect: asymmetric entity sets, year date precision,", "    near-identical summaries. Reproduces the reported factor scores exactly.\"\"\"", "    incoming = _make_incoming(", "        cat_id=cat_id,", "        type_id=type_id,", "        entity_ids=(shared, other),", "        event_date_precision=\"year\",", "    )", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4(), uuid4()},", "        summary_similarity=0.9454,", "        event_date_precision=\"year\",", "    )", "    return incoming, candidate", "", "", "def _recheck_candidate(*, cat_id, type_id, shared, summary_similarity=0.95, days=40):", "    \"\"\"Candidate shaped like the reported defect: near-identical text, weak structure.", "", "    Entity overlap and temporal are deliberately low so the composite lands inside", "    the needs_llm band rather than auto-merging -- which is the only place a", "    rejection, and therefore a recheck, can happen.", "    \"\"\"", "    return _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4(), uuid4(), uuid4(), uuid4()},", "        event_date=datetime.date(2026, 5, 1) + datetime.timedelta(days=days),", "        summary_similarity=summary_similarity,", "    )", "", "", "async def test_a_rejection_the_scorer_disagrees_with_is_asked_again():", "    \"\"\"One \"different event\" answer is not final when the score contradicts it.", "", "    The reported defect: the scorer ranked the true sibling first out of 150 and", "    the model rejected it, so one story became two events. A second model is", "    asked before that answer is accepted.", "    \"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"primary says no\"),", "            DisambiguationOutput(same_event=True, confidence=0.92, rationale=\"second says yes\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == candidate.source_event_id", "    assert [a.recheck for a in outcome.llm_attempts] == [False, True]", "    # The second opinion is asked of a different model, or it is not a second opinion.", "    assert llm.captured_kwargs[1][\"chat_model_override\"] is ChatModel.CLAUDE_HAIKU_4_5", "    # Recorded, not just requested: the decision log and the ask-twice guard both", "    # read this field, so a lost override would be invisible without it.", "    assert [a.chat_model for a in outcome.llm_attempts] == [", "        llm.chat_model_name,", "        ChatModel.CLAUDE_HAIKU_4_5.value,", "    ]", "", "", "async def test_a_qualifying_rejection_is_rechecked_even_when_another_scores_higher():", "    \"\"\"The recheck follows the floors, not the composite ranking.", "", "    Composite blends four factors that barely separate the two populations, so a", "    structurally strong candidate can outrank the genuine sibling while carrying", "    text that says nothing. Gating the second opinion on being top-composite", "    would skip exactly the shape this exists for.", "    \"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared, a, b = uuid4(), uuid4(), uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, a, b, uuid4()))", "", "    # Near-identical text, weak structure: the reported shape, queued first.", "    sibling = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "    # Strong structure, text that identifies nothing: outranks on composite, and", "    # its own summary is far below the recheck floor.", "    decoy = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, a},", "        event_date=datetime.date(2026, 5, 1),", "        summary_similarity=0.60,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"primary says no\"),", "            DisambiguationOutput(same_event=True, confidence=0.92, rationale=\"second says yes\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [decoy, sibling], cfg, llm)", "", "    by_id = {s.source_event_id: s for s in outcome.candidate_scores}", "    assert (", "        by_id[decoy.source_event_id].composite_score", "        > by_id[sibling.source_event_id].composite_score", "    ), \"the decoy must outrank the sibling on composite, or this proves nothing\"", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == sibling.source_event_id", "    assert [a.recheck for a in outcome.llm_attempts] == [False, True]", "", "", "async def test_an_unaffirmed_lower_ranked_recheck_leaves_every_candidate_separate():", "    \"\"\"Distinct events stay separate however the second opinion is routed.", "", "    Dropping the composite-top gate widens which rejection earns a recheck, not", "    what a recheck may conclude: a merge still requires the second model to", "    affirm that exact pair, so an unaffirmed recheck leaves every candidate its", "    own event.", "    \"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared, a = uuid4(), uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, a, uuid4(), uuid4())", "    )", "", "    # Queued first on text, and clears both floors: the widened path adjudicates it.", "    lower_ranked = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "    # Outranks it on composite, so under the old gate this one held the slot.", "    higher_ranked = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, a},", "        event_date=datetime.date(2026, 5, 1),", "        summary_similarity=0.60,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.7, rationale=\"primary: no\"),", "            DisambiguationOutput(same_event=False, confidence=0.8, rationale=\"second: also no\"),", "            DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"other: no\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [higher_ranked, lower_ranked], cfg, llm)", "", "    # The widened path was genuinely exercised, or this proves nothing.", "    assert [att.recheck for att in outcome.llm_attempts] == [False, True, False]", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert outcome.chosen_source_event_id is None", "", "", "async def test_only_one_rejection_per_message_earns_a_second_opinion():", "    \"\"\"The latency bound is one extra call, not one per qualifying rejection.", "", "    At a cap generous enough to afford two, nothing but this guard stops a", "    message from spending the budget on repeated second opinions.", "    \"\"\"", "    cfg = MatchScoringConfig(high_threshold=0.82, low_threshold=0.55, max_llm_calls=4)", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    first = _recheck_candidate(", "        cat_id=cat_id, type_id=type_id, shared=shared, summary_similarity=0.96", "    )", "    second = _recheck_candidate(", "        cat_id=cat_id, type_id=type_id, shared=shared, summary_similarity=0.95", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.7, rationale=\"no\")] * 4", "    )", "    outcome = await decide_match(incoming, [first, second], cfg, llm)", "", "    assert [a.recheck for a in outcome.llm_attempts].count(True) == 1", "    assert outcome.decision is MatchDecision.CREATE_NEW", "", "", "async def test_a_qualifying_rejection_later_in_the_queue_still_gets_its_recheck(monkeypatch):", "    \"\"\"Budget is spent, not merely counted down.", "", "    Queue order is summary-first, so a candidate can sit ahead of the real", "    sibling on text alone while missing the composite floor. An off-by-one on", "    the budget guard would strand the sibling with slots still unspent.", "    \"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics,", "        \"incr\",", "        lambda metric, tags=None, value=1: emitted.append((metric, tags or [])),", "    )", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    # Strongest text in the queue, but too little structure to clear the composite floor.", "    decoy = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared} | {uuid4() for _ in range(11)},", "        event_date=datetime.date(2026, 5, 1) + datetime.timedelta(days=92),", "        summary_similarity=0.98,", "    )", "    sibling = _recheck_candidate(", "        cat_id=cat_id, type_id=type_id, shared=shared, summary_similarity=0.95", "    )", "", "    by_id = {", "        s.source_event_id: s for s in (score_candidate(incoming, c, cfg) for c in (decoy, sibling))", "    }", "    assert by_id[decoy.source_event_id].composite_score < cfg.llm_recheck_min_composite", "    assert by_id[sibling.source_event_id].composite_score >= cfg.llm_recheck_min_composite", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.7, rationale=\"decoy: no\"),", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"primary: no\"),", "            DisambiguationOutput(same_event=True, confidence=0.92, rationale=\"second: yes\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [decoy, sibling], cfg, llm)", "", "    assert [a.recheck for a in outcome.llm_attempts] == [False, False, True]", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == sibling.source_event_id", "    rechecks = [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"]", "    assert rechecks == [[\"outcome:overturned\"]]", "", "", "async def test_a_recheck_the_budget_cannot_afford_is_counted(monkeypatch):", "    \"\"\"A cap that never affords a second opinion has to be visible, not silent.\"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics,", "        \"incr\",", "        lambda metric, tags=None, value=1: emitted.append((metric, tags or [])),", "    )", "    cfg = MatchScoringConfig(high_threshold=0.82, low_threshold=0.55, max_llm_calls=1)", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert [a.recheck for a in outcome.llm_attempts] == [False]", "    rechecks = [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"]", "    assert rechecks == [[\"outcome:skipped_no_budget\"]]", "", "", "async def test_a_recheck_that_agrees_with_the_rejection_leaves_the_create(monkeypatch):", "    \"\"\"Both models saying \"different\" is the answer, not a tie to break.\"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics,", "        \"incr\",", "        lambda metric, tags=None, value=1: emitted.append((metric, tags or [])),", "    )", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\"),", "            DisambiguationOutput(same_event=False, confidence=0.95, rationale=\"also no\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert outcome.chosen_source_event_id is None", "    assert [a.recheck for a in outcome.llm_attempts] == [False, True]", "    # An upheld rejection is half the overturn-share denominator the runbook reads,", "    # so the tag has to be the one the docs name.", "    assert [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"] == [[\"outcome:upheld\"]]", "", "", "async def test_a_recheck_outage_does_not_fail_a_message_the_primary_answered(monkeypatch):", "    \"\"\"The regression this design most easily causes.", "", "    A second opinion is optional. Letting its outage produce ``RETRY_OR_DLQ``", "    would fail a message that the primary had already answered cleanly.", "    \"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics,", "        \"incr\",", "        lambda metric, tags=None, value=1: emitted.append((metric, tags or [])),", "    )", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\"),", "            RuntimeError(\"second model down\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert outcome.decision is not MatchDecision.RETRY_OR_DLQ", "    assert outcome.llm_attempts[-1].error == \"RuntimeError\"", "    assert outcome.llm_attempts[-1].recheck is True", "    # Counted as an error, not folded into upheld: otherwise a provider outage", "    # reads as the second model agreeing.", "    assert [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"] == [[\"outcome:error\"]]", "", "", "async def test_a_confirmed_first_pass_is_not_asked_again(monkeypatch):", "    \"\"\"A second opinion is for rejections; confirming a yes would waste the slot.", "", "    The candidate clears both recheck floors, so only the answer itself keeps it", "    out of the second-opinion path.", "    \"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics,", "        \"incr\",", "        lambda metric, tags=None, value=1: emitted.append((metric, tags or [])),", "    )", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=True, confidence=0.9, rationale=\"yes\")]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert len(outcome.llm_attempts) == 1", "    assert [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"] == []", "", "", "async def test_a_first_pass_error_still_routes_retry_and_asks_no_second_model():", "    \"\"\"The recheck is additive: it must not soften the partial-outage rule.\"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator([RuntimeError(\"primary down\")])", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.RETRY_OR_DLQ", "    assert len(outcome.llm_attempts) == 1", "    assert outcome.llm_attempts[0].recheck is False", "", "", "async def test_a_rejection_below_the_trigger_is_not_asked_again():", "    \"\"\"Read off the config, so retuning the default cannot silently void this.\"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        shared=shared,", "        summary_similarity=cfg.llm_recheck_min_summary - 0.02,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert len(outcome.llm_attempts) == 1", "    assert llm.calls == [candidate.source_event_id]", "", "", "async def test_near_identical_text_alone_does_not_earn_a_second_opinion():", "    \"\"\"Both floors are required: the composite one is not decorative.", "", "    Text can be near-identical while the structure around it says nothing --", "    a heavily-tagged prior event and a stale date drag the composite under the", "    floor. That rejection stands on the first answer.", "    \"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared} | {uuid4() for _ in range(11)},", "        event_date=datetime.date(2026, 5, 1) + datetime.timedelta(days=92),", "        summary_similarity=0.98,", "    )", "", "    scored = score_candidate(incoming, candidate, cfg)", "    assert scored.decision is MatchDecision.NEEDS_LLM", "    assert scored.summary_similarity_score >= cfg.llm_recheck_min_summary", "    assert scored.composite_score < cfg.llm_recheck_min_composite", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.7, rationale=\"no\")]", "    )", "    outcome = await decide_match(incoming, [candidate], cfg, llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert [a.recheck for a in outcome.llm_attempts] == [False]", "", "", "async def test_an_unmeasured_summary_is_not_strong_evidence():", "    \"\"\"A missing similarity is not a high one; the recheck needs a measured value.\"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4()))", "    candidate = _make_candidate(", "        cat_id=cat_id,", "        type_id=type_id,", "        candidate_entity_ids={shared, uuid4()},", "        summary_similarity=None,", "    )", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\")]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert len(outcome.llm_attempts) == 1", "", "", "async def test_an_answer_already_from_the_second_model_is_not_asked_twice():", "    \"\"\"The primary can fall back on its own; rechecking that asks the same model.\"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [", "            (", "                DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\"),", "                ChatModel.CLAUDE_HAIKU_4_5,", "            )", "        ]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.CREATE_NEW", "    assert len(outcome.llm_attempts) == 1", "", "", "async def test_the_recheck_spends_a_dispatch_slot_rather_than_adding_one():", "    \"\"\"The latency invariant: total calls stay bounded by ``max_llm_calls``.", "", "    One call is capped at 30s and the SQS visibility timeout is 120s. A recheck", "    that added a fourth call would put the worst case exactly on that boundary,", "    where the message redelivers and one of three attempts is burned.", "    \"\"\"", "    cfg = _config()", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidates = [", "        _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared, summary_similarity=s)", "        for s in (0.97, 0.96, 0.95, 0.94)", "    ]", "", "    llm = _StubLLMDisambiguator(", "        [DisambiguationOutput(same_event=False, confidence=0.9, rationale=\"no\")] * 6", "    )", "    outcome = await decide_match(incoming, candidates, cfg, llm)", "", "    assert len(llm.calls) == cfg.max_llm_calls", "    assert len(outcome.llm_attempts) == cfg.max_llm_calls", "    # Exactly one of them is the recheck; the rest are first-pass dispatch.", "    assert sum(a.recheck for a in outcome.llm_attempts) == 1", "", "", "async def test_each_recheck_counts_its_outcome(monkeypatch):", "    \"\"\"The overturn share is the only signal for how often the models disagreed.\"\"\"", "    emitted: list[tuple[str, list[str]]] = []", "    monkeypatch.setattr(", "        mc_module.ess_metrics, \"incr\", lambda name, tags=None: emitted.append((name, tags or []))", "    )", "", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming = _make_incoming(", "        cat_id=cat_id, type_id=type_id, entity_ids=(shared, uuid4(), uuid4(), uuid4())", "    )", "    candidate = _recheck_candidate(cat_id=cat_id, type_id=type_id, shared=shared)", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"no\"),", "            DisambiguationOutput(same_event=True, confidence=0.92, rationale=\"yes\"),", "        ]", "    )", "    await decide_match(incoming, [candidate], _config(), llm)", "", "    rechecks = [t for n, t in emitted if n == \"ess.scoring.llm_recheck\"]", "    assert rechecks == [[\"outcome:overturned\"]]", "", "", "async def test_the_reported_pair_shape_resolves_to_one_event():", "    \"\"\"The defect's own shape, reproduced from its measured factor scores.", "", "    Asymmetric entity sets, year date precision and near-identical summaries put", "    the pair in the disambiguation band; the model rejected it and the pipeline", "    accepted that as final, so one story became two events.", "", "    Coverage stops at the decision: this asserts the pair resolves to one chosen", "    source event. Landing both documents on that event is the merge-link writer's", "    half, unchanged here and covered against a real database by", "    ``test_merge_link_service.py`` --", "    ``test_confirmed_merge_updates_source_event_and_writes_article_linked_change``", "    and ``test_ac4_platform_document_evidence_stores_doc_id_and_raw_event_id``.", "    \"\"\"", "    cat_id, type_id = uuid4(), uuid4()", "    shared = uuid4()", "    incoming, candidate = _reported_shape(", "        cat_id=cat_id, type_id=type_id, shared=shared, other=uuid4()", "    )", "", "    scored = score_candidate(incoming, candidate, _config())", "    assert scored.decision is MatchDecision.NEEDS_LLM", "    assert scored.entity_overlap_score == pytest.approx(0.20, abs=0.01)", "    assert scored.temporal_score == pytest.approx(0.40, abs=0.01)", "    assert scored.composite_score == pytest.approx(0.699, abs=0.005)", "", "    llm = _StubLLMDisambiguator(", "        [", "            DisambiguationOutput(same_event=False, confidence=0.68, rationale=\"reported answer\"),", "            DisambiguationOutput(same_event=True, confidence=0.92, rationale=\"second opinion\"),", "        ]", "    )", "    outcome = await decide_match(incoming, [candidate], _config(), llm)", "", "    assert outcome.decision is MatchDecision.MERGE_CONFIRMED", "    assert outcome.chosen_source_event_id == candidate.source_event_id", "    assert [a.recheck for a in outcome.llm_attempts] == [False, True]"], "blocks": [{"start": 1, "end": 32, "label": "Imports and module setup"}, {"start": 33, "end": 42, "label": "class _StubLLMDisambiguator"}, {"start": 43, "end": 52, "label": "_StubLLMDisambiguator.__init__"}, {"start": 53, "end": 68, "label": "_StubLLMDisambiguator.disambiguate"}, {"start": 69, "end": 72, "label": "def _config"}, {"start": 73, "end": 92, "label": "def _make_incoming"}, {"start": 93, "end": 113, "label": "def _make_candidate"}, {"start": 114, "end": 144, "label": "def test_merge_confirmed_short_circuits_llm"}, {"start": 145, "end": 175, "label": "def test_two_ambiguous_llm_returns_false_routes_create_new"}, {"start": 176, "end": 202, "label": "def test_first_llm_true_short_circuits_remaining_calls"}, {"start": 203, "end": 222, "label": "def test_all_llm_errors_route_retry_or_dlq"}, {"start": 223, "end": 249, "label": "def test_first_error_stops_iteration_immediately"}, {"start": 250, "end": 278, "label": "def test_error_after_prior_false_still_routes_retry_or_dlq"}, {"start": 279, "end": 313, "label": "def test_tie_break_uses_ascending_uuid_terminator"}, {"start": 314, "end": 327, "label": "def test_empty_candidates_routes_create_new"}, {"start": 328, "end": 350, "label": "def test_all_below_low_threshold_routes_create_new_no_llm"}, {"start": 351, "end": 405, "label": "def test_orchestrator_threads_context_fields_to_disambiguator"}, {"start": 406, "end": 433, "label": "def test_both_empty_same_type_consults_llm_instead_of_auto_merging"}, {"start": 434, "end": 456, "label": "def test_both_empty_same_type_llm_true_still_merges"}, {"start": 457, "end": 491, "label": "def test_coarse_signals_only_create_new_without_llm"}, {"start": 492, "end": 533, "label": "def test_asymmetric_entity_absence_creates_new_without_llm"}, {"start": 534, "end": 567, "label": "def test_orchestrator_handles_missing_context_with_safe_defaults"}, {"start": 568, "end": 605, "label": "def test_llm_attempt_records_actual_chat_model_used"}, {"start": 606, "end": 634, "label": "def test_decide_match_emits_structured_log_on_merge_confirmed"}, {"start": 635, "end": 650, "label": "def test_decide_match_logs_empty_top_blob_when_no_candidates"}, {"start": 651, "end": 709, "label": "def test_decide_match_log_excludes_summaries_key_details_entities_and_rationale"}, {"start": 710, "end": 747, "label": "def test_decide_match_log_excludes_exception_message_on_llm_error"}, {"start": 748, "end": 802, "label": "def test_decision_log_pairs_each_blob_with_its_candidate"}, {"start": 803, "end": 855, "label": "def test_decision_log_names_every_scored_candidate_beyond_the_blob_cap"}, {"start": 856, "end": 888, "label": "def test_a_barely_confident_rejection_is_as_decisive_as_a_certain_one"}, {"start": 889, "end": 913, "label": "def test_a_confident_rejection_of_unrelated_text_is_the_same_path"}, {"start": 914, "end": 952, "label": "def test_the_disambiguation_queue_is_capped_at_max_llm_calls"}, {"start": 953, "end": 997, "label": "def test_the_true_sibling_is_asked_before_stronger_scoring_distractors"}, {"start": 998, "end": 1028, "label": "def test_a_candidate_with_no_measured_similarity_is_asked_last"}, {"start": 1029, "end": 1067, "label": "def test_each_decision_counts_its_outcome_and_every_llm_call"}, {"start": 1068, "end": 1116, "label": "def test_every_llm_answer_counts_its_classification"}, {"start": 1117, "end": 1148, "label": "def test_a_failed_call_counts_as_an_error_result_not_a_rejection"}, {"start": 1149, "end": 1167, "label": "def _reported_shape"}, {"start": 1168, "end": 1183, "label": "def _recheck_candidate"}, {"start": 1184, "end": 1218, "label": "def test_a_rejection_the_scorer_disagrees_with_is_asked_again"}, {"start": 1219, "end": 1261, "label": "def test_a_qualifying_rejection_is_rechecked_even_when_another_scores_higher"}, {"start": 1262, "end": 1302, "label": "def test_an_unaffirmed_lower_ranked_recheck_leaves_every_candidate_separate"}, {"start": 1303, "end": 1328, "label": "def test_only_one_rejection_per_message_earns_a_second_opinion"}, {"start": 1329, "end": 1379, "label": "def test_a_qualifying_rejection_later_in_the_queue_still_gets_its_recheck"}, {"start": 1380, "end": 1406, "label": "def test_a_recheck_the_budget_cannot_afford_is_counted"}, {"start": 1407, "end": 1437, "label": "def test_a_recheck_that_agrees_with_the_rejection_leaves_the_create"}, {"start": 1438, "end": 1473, "label": "def test_a_recheck_outage_does_not_fail_a_message_the_primary_answered"}, {"start": 1474, "end": 1502, "label": "def test_a_confirmed_first_pass_is_not_asked_again"}, {"start": 1503, "end": 1519, "label": "def test_a_first_pass_error_still_routes_retry_and_asks_no_second_model"}, {"start": 1520, "end": 1544, "label": "def test_a_rejection_below_the_trigger_is_not_asked_again"}, {"start": 1545, "end": 1577, "label": "def test_near_identical_text_alone_does_not_earn_a_second_opinion"}, {"start": 1578, "end": 1598, "label": "def test_an_unmeasured_summary_is_not_strong_evidence"}, {"start": 1599, "end": 1621, "label": "def test_an_answer_already_from_the_second_model_is_not_asked_twice"}, {"start": 1622, "end": 1650, "label": "def test_the_recheck_spends_a_dispatch_slot_rather_than_adding_one"}, {"start": 1651, "end": 1676, "label": "def test_each_recheck_counts_its_outcome"}, {"start": 1677, "end": 1713, "label": "def test_the_reported_pair_shape_resolves_to_one_event"}], "lineCount": 1713, "sha256": "986aa29f03bc340752bb7a90af40a0d5a215c34322f61ba6852e3109e9de476f", "endsWithNewline": true});
